import os
import ast

for root, dirs, files in os.walk('app'):
    for file in files:
        if not file.endswith('.py') or file == 'auth.py':
            continue
        path = os.path.join(root, file)
        with open(path, 'r') as f:
            content = f.read()
        try:
            tree = ast.parse(content)
        except Exception:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef):
                lines = content.splitlines()
                func_lines = lines[node.lineno - 1: node.end_lineno]
                func_code = '\n'.join(func_lines)
                if 'legacy_auth' in func_code:
                    is_write = False
                    path_lower = path.lower()
                    if any(kw in path_lower for kw in ['create', 'update', 'delete', 'save', 'write']):
                        is_write = True
                    func_body_lower = func_code.lower()
                    if any(kw in func_body_lower for kw in ['created', 'updated', 'create_', 'update_', 'delete_', 'save_', 'write_']):
                        is_write = True
                    if any(kw in func_code for kw in ['POST', 'PUT', 'PATCH']):
                        is_write = True

                    scope = 'write' if is_write else 'read'
                    print(f"{path}::{node.name} -> scope={scope}")
